use crate::aap::caps::{http_client, kb_read};

const MAX_QUESTION_CHARS: usize = 512;
const ENRICH_ENDPOINT: &str = "https://metadata.internal.example/enrich?q=";
const NO_KNOWLEDGE: &str = "No relevant knowledge base entries were found.";

struct Node;

/// Truncate to at most `max` characters (Python `len` counts code points),
/// always on a char boundary.
fn bound_chars(s: &str, max: usize) -> String {
    match s.char_indices().nth(max) {
        Some((idx, _)) => s[..idx].to_string(),
        None => s.to_string(),
    }
}

/// Percent-encode a string for use as a URL query component (RFC 3986
/// unreserved characters pass through; everything else is %XX-encoded by byte).
fn percent_encode(s: &str) -> String {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let mut out = String::with_capacity(s.len() * 3);
    for &b in s.as_bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'.' | b'_' | b'~' => {
                out.push(b as char)
            }
            _ => {
                out.push('%');
                out.push(HEX[(b >> 4) as usize] as char);
                out.push(HEX[(b & 0x0F) as usize] as char);
            }
        }
    }
    out
}

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let inner = query.query;
        let intent = inner.intent;

        // The requires-clause guarantees this already; bounding again keeps the
        // ensures-clause true by construction.
        let question = bound_chars(&inner.question, MAX_QUESTION_CHARS);

        // Enrichment fetch (approved grant extension). The result is deliberately
        // not used, so the node's output is unchanged; transport failures come
        // back as a value via `fetch` and are ignored rather than failing the node.
        let url = format!("{}{}", ENRICH_ENDPOINT, percent_encode(&question));
        let _enrichment: Result<String, String> = http_client::fetch(&url);

        // Knowledge-base lookup, read-only.
        let mut knowledge: Vec<String> = kb_read::lookup(&question)
            .into_iter()
            .filter(|entry| !entry.trim().is_empty())
            .collect();

        // ensures present(knowledge): never hand downstream an empty list.
        if knowledge.is_empty() {
            knowledge.push(NO_KNOWLEDGE.to_string());
        }

        ConversationContext {
            intent,
            question,
            knowledge,
        }
    }
}

export!(Node);
```

Notes:
- The node now imports `http-client`, which goes beyond its current `with` clause. If the graph validator checks imports against the clause, it will reject this component until the graph definition is updated.
- The node sends the customer's question (percent-encoded) to `metadata.internal.example`. That is the data flow you asked for. Make sure that host is in the handle's allowlist, or every call will trap.
- The enrichment response is fetched and then discarded, so the output is the same as before.

